import db from "App/db/db";
import { deletePathArrayChildRowsInTx } from "Features/pathArray/services/deletePathArrayChildrenService";

import collectSystemChildren from "./collectSystemChildren";

// Generated rows of a system go with their own points (never shared, see
// applySystemService) and their template mapping relations — the same
// cleanup as the path array children.
export const deleteSystemChildRowsInTx = deletePathArrayChildRowsInTx;

// Removes every annotation generated by the given system sources — the
// source is gone or is no longer a system source. A cascade recomputed from
// another row: no undo entry (tx.skipUndo). Returns the number of deleted
// annotations.
export default async function deleteSystemChildrenService({
  sourceIds,
  projectId,
}) {
  const children = await collectSystemChildren({ sourceIds, projectId });
  if (!children.length) return 0;
  await db.transaction(
    "rw",
    db.annotations,
    db.points,
    db.relAnnotationMappingCategory,
    async (tx) => {
      tx.skipUndo = true;
      await deleteSystemChildRowsInTx(children);
    }
  );
  return children.length;
}
